import type { Db } from 'mongodb';
import { COLLECTIONS } from '../db/collections.js';
import { ensureIndexesFor } from '../db/indexes.js';
import type { Migration } from './types.js';

/**
 * Teros Remote Phase 1 (docs/specs/remote/teros-remote.md § Data Model, REQ-5):
 *
 * Create the `remote_devices` collection with its indexes. One record per
 * paired machine, created by the RemoteDeviceGateway on the first
 * authenticated `hello` and updated on every connect/disconnect/heartbeat:
 *
 *   - deviceId (unique) — stable id generated by the daemon at pairing
 *   - appId — the bound `mca.teros.remote` app instance (one machine per instance)
 *   - tokenHash — sha256 of the device key; mirrors the app instance's stored
 *     user secret (TEROS_REMOTE_KEY) so the gateway can look a hello up fast
 *   - workspaceId + status — the app panel's online/offline view (REQ-13)
 *   - ownerId — the user who pasted the key into the app instance
 *
 * The final index shape is declared in src/db/indexes.ts (GOV-4); this
 * migration applies the same registry entry so a fresh DB and production
 * converge. Idempotent: ensureIndex is a no-op when the index exists.
 */
const migration: Migration = {
  description: 'Teros Remote P1: create remote_devices collection (+indexes)',

  async up(db: Db): Promise<void> {
    await ensureIndexesFor(db, [COLLECTIONS.remoteDevices]);
    console.log(
      '[Migration] Created remote_devices collection + indexes (deviceId_unique, appId_1, tokenHash_1, workspaceId_1_status_1, ownerId_1)',
    );
  },

  async down(db: Db): Promise<void> {
    // Drop the indexes only — the collection stays (dropping it would lose
    // pairing records; the daemon would re-create them on the next hello anyway,
    // but lastSeenAt history is worth keeping).
    const col = db.collection(COLLECTIONS.remoteDevices);
    for (const name of [
      'deviceId_unique',
      'appId_1',
      'tokenHash_1',
      'workspaceId_1_status_1',
      'ownerId_1',
    ]) {
      try {
        await col.dropIndex(name);
      } catch (err) {
        // IndexNotFound (27) / NamespaceNotFound (26) — already gone; ignore.
        const code = (err as { code?: number }).code;
        if (code !== 27 && code !== 26) throw err;
      }
    }
    console.log('[Migration] Dropped remote_devices indexes');
  },
};

export default migration;
